#include "../tlv_codec.h"
#include "test_harness.h"
#include <stddef.h>
#include <string.h>

TEST(test_tlv_encode_sentinel) {
    uint8_t backing[64];
    memset(backing, 0xFF, sizeof(backing));
    tlv_encoder_t enc;
    tlv_encoder_init(&enc, backing, sizeof(backing));
    tlv_encode(&enc, 0x0001, (const uint8_t *)"AB", 2);
    size_t used = tlv_encoder_len(&enc);
    /* sentinel: byte after encoded data must be untouched */
    if (used > 0 && used < sizeof(backing)) {
        ASSERT_EQ(backing[used], 0xFF);
    }
}

